from pathlib import Path
import datetime,hashlib,json,os,re,shutil,signal,socket,stat,subprocess,time
from urllib.parse import urlparse,parse_qs
R=Path('/home/andy/.codex/worktrees/background-jobs/sandbox-crypto');LAB=Path.home()/'.local/state/openshell-lab';OS=Path.home()/'.local/opt/openshell-0.1.3/bin';HEAD='f964a05018fc85ffdd09f5af00c8c5c30a31c841'
def g(*a):return subprocess.check_output(['git',*a],cwd=R,text=True).strip()
assert g('rev-parse','HEAD')==HEAD and not g('status','--porcelain')
a=json.loads(Path('/tmp/lab30-final-owned-runtime-identities.json').read_bytes());assert a['source_head']==HEAD
marker=json.loads((LAB/'provisioning-workspace.created').read_bytes());assert marker['source_head']==HEAD and marker['project']=='lab30' and marker['run_id']==a['run_id']
initial=json.loads((LAB/'evidence/provisioning-workspace-initial.json').read_bytes())['payload']['sql']['environments'];owned={v['sandbox_id'] for v in initial};assert len(owned)==2
env=dict(os.environ,XDG_CONFIG_HOME=str(LAB/'config'),XDG_STATE_HOME=str(LAB/'state'),XDG_DATA_HOME=str(LAB/'data'),OPENSHELL_LOCAL_TLS_DIR=str(LAB/'state/openshell/tls'),OPENSHELL_TELEMETRY_ENABLED='false',PATH=str(OS)+os.pathsep+os.environ.get('PATH',''))
proc=subprocess.run([str(OS/'openshell'),'sandbox','list','--all-workspaces','--ids','--page-size','3'],cwd=R,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=15)
assert proc.returncode==0 and len(proc.stdout)<=4096 and not proc.stderr;ids=set(proc.stdout.decode().split());assert ids==owned and all(re.fullmatch('[0-9a-f-]{36}',v) for v in ids)
def private(name):
 fd=os.open(LAB/name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
 try:
  s=os.fstat(fd);assert stat.S_ISREG(s.st_mode) and s.st_uid==os.getuid() and stat.S_IMODE(s.st_mode)==0o600 and s.st_size<=4096
  raw=os.read(fd,4097);assert len(raw)<=4096;return raw,s
 finally:os.close(fd)
login,st=private('provisioning-workspace-private.json');assert (st.st_dev,st.st_ino,st.st_uid,stat.S_IMODE(st.st_mode))==tuple(a['private_login_metadata_only'][k] for k in ('device','inode','uid','mode'))
info=json.loads(login);token,_=private('worker/client-a.token');secrets=[token.strip(),info['login_url'].encode()]+[v.encode() for values in parse_qs(urlparse(info['login_url']).query).values() for v in values if len(v)>24]
export=Path('/tmp/lab30-failed-ready-gate-public-evidence');export.mkdir(mode=0o700)
public={}
def save(p):
 s=p.lstat();assert stat.S_ISREG(s.st_mode) and s.st_uid==os.getuid() and s.st_nlink==1 and s.st_size<=2*1024*1024
 raw=p.read_bytes();assert all(secret not in raw for secret in secrets);dest=export/p.name
 with dest.open('xb') as out:out.write(raw)
 public[p.name]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
save(LAB/'provisioning-workspace.created')
for p in sorted((LAB/'evidence').glob('provisioning-workspace-*.json')):save(p)
pid=a['workspace_pid'];assert Path(f'/proc/{pid}/stat').read_text().split()[21]==a['workspace_start_identity'];os.kill(pid,signal.SIGTERM)
for _ in range(150):
 if not Path(f'/proc/{pid}').exists():break
 time.sleep(.1)
assert not Path(f'/proc/{pid}').exists() and not (LAB/'provisioning-workspace-private.json').exists()
for p in sorted((LAB/'evidence').glob('provisioning-workspace-*cleanup*.json')):
 if p.name not in public:save(p)
rawlog=Path('/tmp/lab30-failed-ready-gate-teardown.raw.log');fd=os.open(rawlog,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
try:done=subprocess.run(['bash','.agents/labs/lab_down.sh'],cwd=R,stdout=fd,stderr=subprocess.STDOUT,timeout=150)
finally:os.close(fd)
assert done.returncode==0 and not LAB.exists();raw=rawlog.read_bytes();assert len(raw)<131072 and all(secret not in raw for secret in secrets)
with Path('/tmp/lab30-failed-ready-gate-teardown.log').open('xb') as out:out.write(raw)
rawlog.unlink()
startup=json.loads(Path('/tmp/lab30-final-owned-startup-completed.json').read_bytes());registration=next(s for s in startup['steps'] if 'private_file' in s);rawpath=Path(registration['private_file']);s=rawpath.lstat();assert stat.S_ISREG(s.st_mode) and not rawpath.is_symlink();assert (s.st_dev,s.st_ino,s.st_uid,stat.S_IMODE(s.st_mode))==tuple(registration[k] for k in ('device','inode','uid','mode'));rawpath.unlink()
states={u:subprocess.run(['systemctl','--user','is-active',u],capture_output=True,text=True).stdout.strip() for u in ['openshell-lab-'+v for v in ('workspace','mcp-forward','worker','gateway','middleware','cache','echo')]};assert all(v=='inactive' for v in states.values())
identities=[]
for u in a['units']:
 path=Path('/proc')/str(u['pid'])/'stat';gone=not path.exists() or path.read_text().split()[21]!=u['start_identity'];assert gone;identities.append({'unit':u['unit'],'pid':u['pid'],'original_start_identity_gone':gone})
ports=[]
for port in [8090,8080,8100,8101,50051,17670,a['workspace_port'],35077]:
 attempts={}
 for reusable in (False,True):
  try:
   with socket.socket() as sock:
    if reusable:sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
    sock.bind(('127.0.0.1',port))
   attempts['reusable_bind' if reusable else 'default_bind']='free'
  except OSError as e:attempts['reusable_bind' if reusable else 'default_bind']='errno-'+str(e.errno)
 with socket.socket() as sock:sock.settimeout(.2);listening=sock.connect_ex(('127.0.0.1',port))==0
 assert not listening;ports.append({'port':port,**attempts,'tcp_listening':False})
freeze=json.loads(Path('/tmp/provisioning-root-combined-source-freeze.json').read_bytes());assert all(hashlib.sha256((R/n).read_bytes()).hexdigest()==h for n,h in freeze['inputs'].items());assert not g('status','--porcelain')
result={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_head':HEAD,'run_id':a['run_id'],'status':'partial acceptance failed on normal ready gate overview; preserved; fully torn down','reason':'SQLite substr of empty BLOB gives NULL; summary guard rejects producer ready operation empty string','completed_stages':['init','serve','initial','install'],'unrun_stages':['permission-wait','permission-finish','offline-inspect','idle-inspect','inspect'],'exact_all_workspace_vm_inventory_before_teardown':sorted(ids),'original_environments':initial,'unit_states':states,'original_pid_identities':identities,'workspace_pid_gone':pid,'bootstrap_pid_gone':not Path('/proc/1004095').exists(),'owned_browser_tab_22_closed':True,'private_login_absent':True,'provider_registration_removed_metadata_only':registration['private_file'],'provider_registration_never_read_or_hashed':True,'lab_absent':True,'ports':ports,'product_inputs_unchanged':len(freeze['inputs']),'public_records':public,'exact_live_secret_exclusion_passed':True}
Path('/tmp/lab30-failed-ready-gate-cleanup.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))

