from pathlib import Path
import asyncio,datetime,json,os,stat
import aiohttp
LAB=Path.home()/'.local/state/openshell-lab'
def private(name):
 fd=os.open(LAB/name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
 try:
  s=os.fstat(fd);assert stat.S_ISREG(s.st_mode) and s.st_uid==os.getuid() and stat.S_IMODE(s.st_mode)==0o600 and s.st_size<=4096
  raw=os.read(fd,4097);assert len(raw)<=4096;return raw
 finally:os.close(fd)
async def main():
 info=json.loads(private('provisioning-workspace-private.json'));assert info['source_head']=='f964a05018fc85ffdd09f5af00c8c5c30a31c841'
 marker=json.loads((LAB/'provisioning-workspace.created').read_bytes());base='http://127.0.0.1:'+str(info['port']);token=private('worker/client-a.token').strip();rows=[]
 async with aiohttp.ClientSession(cookie_jar=aiohttp.CookieJar(unsafe=True),timeout=aiohttp.ClientTimeout(total=12)) as http:
  async with http.get(info['login_url'],allow_redirects=False) as response:assert response.status==303;assert len(await response.content.read(4097))<=4096
  for scope,environment in marker['environments'].items():
   for transport in ('worker','gui'):
    if transport=='worker':url='http://127.0.0.1:8100/v1/environments/'+environment+'/provisioning/observations?project_id=lab30';headers={'Authorization':'Bearer '+token.decode()}
    else:url=base+'/api/v0/projects/lab30/environments/'+environment+'/provisioning/observations';headers={}
    async with http.get(url,headers=headers,allow_redirects=False) as response:
     raw=await response.content.read(65537);assert len(raw)<=65536 and token not in raw;value=json.loads(raw)
     row={'scope':scope,'environment_id':environment,'transport':transport,'status':response.status,'bytes':len(raw)}
     if response.status!=200:
      kind=value.get('error',{}).get('kind') if isinstance(value,dict) and isinstance(value.get('error'),dict) else None
      allowed={'unavailable','invalid_request','not_found','observation_unavailable','observation_busy','stale_selection','internal','busy','permission_denied'}
      row['error_kind']=kind if kind in allowed else 'other-or-absent'
      row['top_level_keys']=sorted(k for k in value if k in ('error','kind','message')) if isinstance(value,dict) else []
     else:
      from sandbox_science.contracts.provision_observations import ProvisionObservation
      model=ProvisionObservation.model_validate_json(raw,strict=True);assert model.project_id=='lab30' and model.environment_id==environment
      row.update(current_revision=model.current_revision,queue_total=model.queue_total,gate=model.gate.model_dump(mode='json'))
      Path('/tmp/lab30-final-current-summary-'+scope+'-'+transport+'.json').write_bytes(raw)
     rows.append(row)
 result={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_head':info['source_head'],'run_id':marker['run_id'],'reads':rows}
 Path('/tmp/lab30-final-summary-diagnostic.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
