# SPDX-License-Identifier: MIT
"""Tiny SQLite-owned retained projection corruption probes; no network/services."""
import json,tempfile
from datetime import UTC,datetime
from pathlib import Path
from sandbox_science.contracts import (EnvironmentRevision,ExecutionContext,ProvisionOperation,ProvisionRequest,ProvisionState,ErrorInfo,ErrorKind)
from sandbox_science.contracts.provisioning import CatalogRef
from sandbox_science.contracts.revisions import LockfileRef
from sandbox_science.worker.store import Store,RevisionRecord
now=datetime(2026,10,13,tzinfo=UTC)
op=ProvisionOperation(provision_id='prv-probe',request=ProvisionRequest(operation_id='op-probe',context=ExecutionContext(project_id='p',session_id='s',environment_id='env'),purpose='Synthetic projection test',conda=('networkx',)),state=ProvisionState.AWAITING_PERMISSION,submitted_at=now,catalog=CatalogRef(version=1,sha256='0'*64),error=ErrorInfo(kind=ErrorKind.INTERNAL,message='Synthetic error only'))
rev=EnvironmentRevision(revision=0,fingerprint='0'*32,recorded_at=now,lockfile=LockfileRef(sha256='a'*64,size=3))
results=[]
with tempfile.TemporaryDirectory(prefix='provision-observation-nested-') as tmp:
    store=Store(Path(tmp)/'worker.sqlite3')
    try:
        store.insert_provision(op,'0'*64);store.add_revision('env',RevisionRecord(0,rev.fingerprint,''),rev)
        for kind in ('catalog_duplicate_version','error_duplicate_kind','lockfile_duplicate_size'):
            store._db.execute('UPDATE provisions SET record=?',(op.model_dump_json(),));store._db.execute('UPDATE revision_entries SET record=?',(rev.model_dump_json(),))
            if kind=='catalog_duplicate_version':
                store._db.execute('UPDATE provisions SET record=?',(op.model_dump_json().replace('"version":1','"version":2,"version":1'),))
            elif kind=='error_duplicate_kind':
                store._db.execute('UPDATE provisions SET record=?',(op.model_dump_json().replace('"kind":"internal"','"kind":"unavailable","kind":"internal"'),))
            else:
                store._db.execute('UPDATE revision_entries SET record=?',(rev.model_dump_json().replace('"size":3','"size":4,"size":3'),))
            try:
                if kind.startswith('lockfile'):
                    value=store.provision_observations.revisions('p','env',since=0,after=-1,limit=8,target=None)
                    displayed=value.revisions[0].lockfile.size
                else:
                    value=store.provision_observations.detail('p','env',op.provision_id,since=0,seq=None)
                    displayed=value.catalog.version if kind.startswith('catalog') else str(value.error_kind)
                result={'accepted':True,'displayed':displayed}
            except Exception as exc:
                result={'accepted':False,'error_type':type(exc).__name__,'kind':str(getattr(exc,'kind',''))}
            results.append({'case':kind,**result,'transaction_closed':not store._db.in_transaction})
    finally: store.close()
print(json.dumps({'source_head':'fd6e6811f1fcc170bf2a2d185f80adc0da1a55af','results':results},indent=2))

